import {providerRows,projectedProviderCount} from './whichgrocer.mjs';

export const MAX_CAPTURE_AGE_MS=3600000;
export const MAX_PROVIDER_ROWS=1000;

// Capture time must be recorded when the connector actually returns, never
// generated by this importer. Replaying a file cannot renew its freshness.
export function prepareProviderSnapshot(snapshot,now=Date.now()){
 if(!snapshot||Array.isArray(snapshot)||typeof snapshot!=='object')throw Error('Publishing requires a capture envelope with retrieved_at and pages');
 const captured=typeof snapshot.retrieved_at==='string'?Date.parse(snapshot.retrieved_at):NaN;
 if(!Number.isFinite(now)||!Number.isFinite(captured)||captured>now||now-captured>MAX_CAPTURE_AGE_MS)throw Error('Capture timestamp must be valid, not future-dated, and at most one hour old');
 const retrieved_at=new Date(captured).toISOString();
 // The existing price column stores cents. Reject extra precision rather than
 // letting database coercion turn a source price into a different shelf claim.
 const rows=providerRows(snapshot.pages,now).filter(r=>Date.parse(r.source_updated_at)<=captured&&/^\d+(?:\.\d{1,2})?$/.test(String(r.price))).map(r=>({...r,retrieved_at}));
 const received=snapshot.pages.reduce((n,page)=>n+page.data.length,0);
 if(!rows.length)throw Error('Empty or unverified import held for review');
 return {rows,received,accepted:rows.length,rejected_or_duplicate:received-rows.length,retrieved_at};
}

// At most three bounded database calls; no credentials or retailer fetching here.
export async function publishProviderSnapshot(snapshot,db,now=Date.now()){
 const plan=prepareProviderSnapshot(snapshot,now);
 const {count,error}=await db.from('provider_products').select('id',{count:'exact',head:true});
 if(error||!Number.isInteger(count)||count<0)throw Error('Cannot check snapshot budget');
 const existing=await db.from('provider_products').select('id').in('id',plan.rows.map(p=>p.id)).limit(200);
 if(existing.error||!Array.isArray(existing.data))throw Error('Cannot check existing snapshot IDs');
 if(projectedProviderCount(count,plan.rows,existing.data.map(p=>p.id))>MAX_PROVIDER_ROWS)throw Error('Conservative 1000-row budget requires retention review');
 const result=await db.from('provider_products').upsert(plan.rows,{onConflict:'id'});
 if(result.error)throw Error('Provider upsert failed; no successful import recorded');
 return plan;
}

export function boundedProviderFetch(fetcher=globalThis.fetch){
 return (input,init={})=>{
  const callerSignal=init.signal??(input instanceof Request?input.signal:null);
  return fetcher(input,{...init,signal:AbortSignal.any([AbortSignal.timeout(15000),...(callerSignal?[callerSignal]:[])])});
 };
}
